export const getDeleteReactionUrl = (reactionId: number) => {
  return `/api/reactions/${reactionId}`
}

/**
 * @summary リアクションを削除
 */
export const deleteReaction = async (
  reactionId: number,
  options?: RequestInit,
): Promise<NoContentResponse> => {
  const res = await fetch(getDeleteReactionUrl(reactionId), {
    ...options,
    method: 'DELETE',
  })

  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
  if (!res.ok) {
    const err: globalThis.Error & { info?: NoContentResponse; status?: number } =
      new globalThis.Error()
    const data: NoContentResponse = body ? JSON.parse(body) : {}
    err.info = data
    err.status = res.status
    throw err
  }
  const data: NoContentResponse = body ? JSON.parse(body) : {}
  return data
}

export const getDeleteReactionMutationKey = () => ['deleteReaction'] as const

export const getDeleteReactionMutationOptions = <
  TError = globalThis.Error & {
    info?: BadRequestResponse | ForbiddenResponse | NotFoundResponse | InternalServerErrorResponse
    status?: number
  },
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof deleteReaction>>,
    TError,
    DeleteReactionMutationVariables,
    TContext
  >
  fetch?: RequestInit
}): UseMutationOptions<
  Awaited<ReturnType<typeof deleteReaction>>,
  TError,
  DeleteReactionMutationVariables,
  TContext
> => {
  const mutationKey = getDeleteReactionMutationKey()
  const { mutation: mutationOptions, fetch: fetchOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, fetch: undefined }

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof deleteReaction>>,
    DeleteReactionMutationVariables
  > = (props) => {
    const { reactionId } = props ?? {}

    return deleteReaction(reactionId, fetchOptions)
  }

  return { mutationFn, ...mutationOptions }
}

